import { getConfigFilepath } from "@smithy/core/dist-es/submodules/config/shared-ini-file-loader/getConfigFilepath";
import { getSsoSessionData } from "@smithy/core/dist-es/submodules/config/shared-ini-file-loader/getSsoSessionData";
import { parseIni } from "@smithy/core/dist-es/submodules/config/shared-ini-file-loader/parseIni";
import { readFile } from "@smithy/core/dist-es/submodules/config/shared-ini-file-loader/readFile";
const swallowError = () => ({});
export const loadSsoSessionData = async (init = {}) => readFile(init.configFilepath ?? getConfigFilepath())
    .then(parseIni)
    .then(getSsoSessionData)
    .catch(swallowError);
